<?php
class med_cisz_profileHandlerRegistry_registrator { private array $handlers = [ 'Contract_RejectionBy' => med_cisz_contract_rejectionBy_main::class ]; private med_cisz_context $context; public function __construct(med_cisz_context $context) { $this->context = $context; } public function registry(string $resourceProfile, $class): void { if (isset($this->handlers[$resourceProfile])) { throw new LogicException("ResourceHandler for '$resourceProfile' is already registered."); } $this->handlers[$resourceProfile] = $class; } public function get (string $resourceProfile) { $class = $this->handlers[$resourceProfile] ?? throw new UnknownProfileException($resourceProfile); return new $class($this->context); } }